input.content:
/* ============================================================
   DUEL 24 — ZONE CARD ONLINE
   ============================================================ */
:root {
  --bg: #04060d;
  --ink: #eaf3ff;
  --muted: #8ea5c6;
  --dim: #5d7194;
  --cyan: #53e6ff;
  --magenta: #ff4f9d;
  --violet: #9a7bff;
  --gold: #ffcc66;
  --green: #54e6a5;
  --panel: rgba(10, 16, 34, 0.68);
  --panel-solid: #0a1022;
  --line: rgba(126, 178, 255, 0.16);
  --line-strong: rgba(126, 198, 255, 0.34);
  --shadow: 0 24px 80px rgba(0, 0, 0, 0.55);
  --mono: ui-monospace, "SFMono-Regular", "Cascadia Code", "Consolas", monospace;
  --sans: "Segoe UI", "Hiragino Sans", "Yu Gothic UI", "Noto Sans JP", system-ui, sans-serif;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--sans);
  -webkit-font-smoothing: antialiased;
  overscroll-behavior: none;
}

body {
  min-height: 100dvh;
  overflow: hidden;
}

button, input { font: inherit; color: inherit; }
button { cursor: pointer; }
h1, h2, h3, p { margin: 0; }
::selection { background: var(--cyan); color: #041019; }

/* ---------- background ---------- */
.bg-layer {
  position: fixed;
  inset: 0;
  z-index: 0;
  overflow: hidden;
  background:
    radial-gradient(ellipse 80% 60% at 50% -10%, #13214a 0%, transparent 62%),
    radial-gradient(ellipse 55% 45% at 12% 42%, rgba(44, 22, 92, 0.55) 0%, transparent 70%),
    radial-gradient(ellipse 50% 40% at 92% 62%, rgba(12, 62, 91, 0.42) 0%, transparent 72%),
    #04060d;
}
#fx { position: absolute; inset: 0; width: 100%; height: 100%; opacity: 0.9; }
.bg-aurora {
  position: absolute;
  inset: -20%;
  background:
    conic-gradient(from 120deg at 30% 40%, transparent 0deg, rgba(83, 230, 255, 0.08) 60deg, transparent 130deg),
    conic-gradient(from 300deg at 70% 60%, transparent 0deg, rgba(255, 79, 157, 0.07) 60deg, transparent 140deg);
  filter: blur(28px);
  animation: aurora-spin 38s linear infinite;
}
@keyframes aurora-spin { to { transform: rotate(360deg) scale(1.05); } }
.bg-grid {
  position: absolute;
  left: -20%;
  right: -20%;
  bottom: -18%;
  height: 55%;
  background-image:
    linear-gradient(rgba(83, 230, 255, 0.14) 1px, transparent 1px),
    linear-gradient(90deg, rgba(83, 230, 255, 0.14) 1px, transparent 1px);
  background-size: 64px 64px;
  transform: perspective(520px) rotateX(66deg);
  transform-origin: 50% 100%;
  mask-image: linear-gradient(to top, rgba(0, 0, 0, 0.8), transparent 92%);
  -webkit-mask-image: linear-gradient(to top, rgba(0, 0, 0, 0.8), transparent 92%);
  animation: grid-drift 6s linear infinite;
  opacity: 0.55;
}
@keyframes grid-drift { to { background-position: 0 64px, 0 0; } }
.bg-vignette {
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at center, transparent 42%, rgba(2, 4, 10, 0.72) 100%);
}
.scanlines {
  position: fixed;
  inset: 0;
  z-index: 40;
  pointer-events: none;
  opacity: 0.16;
  background: repeating-linear-gradient(to bottom, rgba(255, 255, 255, 0.045) 0 1px, transparent 1px 4px);
  mix-blend-mode: overlay;
}

/* ---------- screens ---------- */
#app { position: relative; z-index: 2; height: 100dvh; }
.screen {
  position: fixed;
  inset: 0;
  display: flex;
  flex-direction: column;
  transition: opacity 0.35s ease, transform 0.35s ease;
}
.screen.hidden {
  opacity: 0;
  pointer-events: none;
  transform: scale(0.995);
}
.lobby-screen {
  overflow-y: auto;
  overflow-x: hidden;
  padding: 18px clamp(14px, 2.4vw, 34px) 14px;
  gap: 16px;
}
.duel-screen { padding: 0 clamp(8px, 1.2vw, 18px) 8px; gap: 6px; overflow: hidden; }

/* ---------- topbar ---------- */
.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  flex: 0 0 auto;
}
.brand { display: flex; align-items: center; gap: 14px; }
.brand-mark {
  position: relative;
  width: 46px;
  height: 52px;
  flex: 0 0 auto;
}
.brand-mark i {
  position: absolute;
  inset: 4px 9px;
  border: 1.5px solid var(--cyan);
  border-radius: 5px;
  background: linear-gradient(160deg, rgba(83, 230, 255, 0.22), rgba(154, 123, 255, 0.05));
  box-shadow: 0 0 24px rgba(83, 230, 255, 0.32), inset 0 0 14px rgba(83, 230, 255, 0.18);
  transform: rotate(-12deg);
  animation: mark-float 4.5s ease-in-out infinite;
}
.brand-mark i:last-child {
  border-color: var(--magenta);
  background: linear-gradient(160deg, rgba(255, 79, 157, 0.2), rgba(154, 123, 255, 0.05));
  box-shadow: 0 0 24px rgba(255, 79, 157, 0.26), inset 0 0 14px rgba(255, 79, 157, 0.14);
  transform: rotate(12deg);
  animation-delay: -2.2s;
}
@keyframes mark-float {
  0%, 100% { transform: rotate(-12deg) translateY(0); }
  50% { transform: rotate(-9deg) translateY(-5px); }
}
.brand-mark i:last-child { animation-name: mark-float-b; }
@keyframes mark-float-b {
  0%, 100% { transform: rotate(12deg) translateY(0); }
  50% { transform: rotate(15deg) translateY(5px); }
}
.brand-copy h1 {
  font-size: clamp(32px, 3.6vw, 46px);
  font-weight: 900;
  letter-spacing: 0.06em;
  line-height: 0.9;
  background: linear-gradient(100deg, #ffffff 10%, #a9ecff 45%, #7f8cff 78%, #ff8cc0 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  filter: drop-shadow(0 0 18px rgba(83, 230, 255, 0.22));
}
.brand-copy h1 span {
  color: transparent;
  -webkit-text-stroke: 1px rgba(255, 255, 255, 0.7);
  margin-left: 4px;
  font-size: 0.68em;
  letter-spacing: 0.02em;
}
.brand-copy p {
  margin-top: 5px;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.4em;
  color: var(--muted);
}
.topbar-right { display: flex; align-items: center; gap: 10px; }
.online-pill, .server-pill {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  height: 34px;
  padding: 0 13px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: rgba(8, 14, 30, 0.55);
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.12em;
  color: var(--muted);
  backdrop-filter: blur(10px);
}
.online-pill b { color: var(--ink); font-weight: 700; }
.pulse-dot, .live-dot i, .live-badge i, .status-tag.live i, .log-live i {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--green);
  box-shadow: 0 0 10px var(--green);
  animation: pulse 1.6s ease-in-out infinite;
}
@keyframes pulse { 0%, 100% { opacity: 1; transform: scale(1); } 50% { opacity: 0.4; transform: scale(0.72); } }
.sig {
  width: 13px;
  height: 9px;
  display: inline-block;
  background: linear-gradient(to top, var(--cyan) 70%, transparent 70%);
  clip-path: polygon(0 100%, 0 40%, 20% 40%, 20% 0, 40% 0, 40% 60%, 60% 60%, 60% 20%, 80% 20%, 80% 50%, 100% 50%, 100% 100%);
  opacity: 0.75;
}
.icon-btn {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: rgba(8, 14, 30, 0.55);
  color: var(--muted);
  font-family: var(--mono);
  transition: 0.2s ease;
}
.icon-btn:hover { color: var(--cyan); border-color: var(--line-strong); background: rgba(83, 230, 255, 0.08); }
.icon-btn .sound-off { display: none; }
body.muted .icon-btn .sound-on { display: none; }
body.muted .icon-btn .sound-off { display: inline; color: var(--magenta); }

/* ---------- lobby grid ---------- */
.lobby-grid {
  flex: 1;
  display: grid;
  grid-template-columns: minmax(400px, 0.92fr) minmax(500px, 1.08fr);
  gap: 16px;
  align-items: stretch;
  min-height: 0;
}
.panel {
  position: relative;
  border: 1px solid var(--line);
  border-radius: 18px;
  background:
    linear-gradient(140deg, rgba(22, 34, 66, 0.62), rgba(6, 10, 24, 0.8) 62%),
    var(--panel);
  box-shadow: var(--shadow), inset 0 1px 0 rgba(180, 220, 255, 0.08);
  backdrop-filter: blur(16px);
  overflow: hidden;
}
.panel::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: radial-gradient(ellipse 70% 40% at 20% 0%, rgba(83, 230, 255, 0.07), transparent 70%);
}
.panel-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  padding: 18px 20px 0;
}
.eyebrow {
  display: block;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.24em;
  color: var(--muted);
}
.eyebrow em { color: var(--cyan); font-style: normal; }
.panel-head h2 {
  margin-top: 5px;
  font-size: clamp(19px, 1.7vw, 24px);
  letter-spacing: 0.03em;
  font-weight: 800;
}
.status-tag {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 26px;
  padding: 0 10px;
  border-radius: 999px;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.1em;
  border: 1px solid rgba(84, 230, 165, 0.3);
  color: var(--green);
  background: rgba(84, 230, 165, 0.07);
  white-space: nowrap;
}
.live-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.2em;
  color: var(--muted);
}
.live-badge i { background: var(--magenta); box-shadow: 0 0 10px var(--magenta); }

/* your room */
.your-room {
  display: flex;
  flex-direction: column;
  padding-bottom: 16px;
  border-color: rgba(83, 230, 255, 0.24);
}
.your-room::after {
  content: "";
  position: absolute;
  left: 8%;
  right: 8%;
  top: -1px;
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--cyan), var(--violet), transparent);
  opacity: 0.8;
}
.code-row {
  display: flex;
  align-items: center;
  gap: 9px;
  margin: 14px 20px 0;
  padding: 8px 11px;
  border: 1px dashed rgba(126, 178, 255, 0.22);
  border-radius: 9px;
  background: rgba(4, 8, 18, 0.5);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.12em;
  color: var(--dim);
}
.code-row strong { color: var(--cyan); font-size: 11px; letter-spacing: 0.16em; }
.code-note { margin-left: auto; color: var(--dim); font-size: 8px; }
.mini-btn {
  border: 1px solid var(--line);
  background: rgba(83, 230, 255, 0.06);
  color: var(--muted);
  border-radius: 5px;
  padding: 2px 7px;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.12em;
  transition: 0.2s;
}
.mini-btn:hover { color: var(--cyan); border-color: var(--line-strong); }

.vs-slots {
  display: grid;
  grid-template-columns: 1fr 46px 1fr;
  align-items: center;
  gap: 8px;
  margin: 14px 20px 0;
}
.slot {
  position: relative;
  min-height: 108px;
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 13px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: linear-gradient(140deg, rgba(24, 39, 76, 0.42), rgba(5, 9, 20, 0.55));
  overflow: hidden;
}
.slot.you { border-color: rgba(83, 230, 255, 0.26); box-shadow: inset 0 0 32px rgba(83, 230, 255, 0.05); }
.slot.opponent.waiting { border-style: dashed; background: rgba(7, 11, 24, 0.42); }
.slot.opponent.ready {
  border-color: rgba(255, 79, 157, 0.34);
  box-shadow: inset 0 0 32px rgba(255, 79, 157, 0.06);
  animation: opponent-ready 1.8s ease-in-out infinite;
}
@keyframes opponent-ready {
  0%, 100% { box-shadow: inset 0 0 30px rgba(255, 79, 157, 0.04); }
  50% { box-shadow: inset 0 0 40px rgba(255, 79, 157, 0.12); border-color: rgba(255, 79, 157, 0.5); }
}
.avatar {
  flex: 0 0 auto;
  width: 46px;
  height: 46px;
  display: grid;
  place-items: center;
  border-radius: 12px;
  border: 1px solid color-mix(in srgb, var(--c) 45%, transparent);
  background:
    radial-gradient(circle at 32% 24%, color-mix(in srgb, var(--c) 32%, transparent), transparent 62%),
    rgba(3, 8, 18, 0.9);
  color: var(--c);
  font-family: var(--mono);
  font-size: 15px;
  font-weight: 800;
  letter-spacing: 0.04em;
  box-shadow: 0 0 22px color-mix(in srgb, var(--c) 20%, transparent), inset 0 0 16px color-mix(in srgb, var(--c) 12%, transparent);
  text-shadow: 0 0 12px var(--c);
}
.slot-info { min-width: 0; display: flex; flex-direction: column; gap: 4px; }
.slot-label { font-family: var(--mono); font-size: 8px; letter-spacing: 0.2em; color: var(--dim); }
.slot-info strong { font-size: 14px; letter-spacing: 0.04em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.slot-info input {
  width: 100%;
  border: 0;
  border-bottom: 1px dashed transparent;
  background: transparent;
  padding: 0;
  font-size: 14px;
  font-weight: 800;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  outline: none;
  transition: 0.2s;
}
.slot-info input:hover, .slot-info input:focus { border-bottom-color: rgba(83, 230, 255, 0.4); }
.rank { font-family: var(--mono); font-size: 8px; letter-spacing: 0.14em; color: var(--dim); }
.rank b { color: var(--gold); font-weight: 600; }
.ready-tag {
  position: absolute;
  top: 9px;
  right: 9px;
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.16em;
  color: var(--green);
  border: 1px solid rgba(84, 230, 165, 0.28);
  border-radius: 4px;
  padding: 2px 5px;
  background: rgba(84, 230, 165, 0.06);
}
.ready-tag.dim { color: var(--dim); border-color: var(--line); background: transparent; }
.vs-mark { display: grid; place-items: center; }
.vs-mark span {
  font-family: var(--mono);
  font-size: 15px;
  font-style: italic;
  font-weight: 800;
  color: var(--ink);
  opacity: 0.7;
  text-shadow: 0 0 16px rgba(255, 255, 255, 0.3);
  animation: vs-pulse 2.6s ease-in-out infinite;
}
@keyframes vs-pulse { 0%, 100% { transform: scale(1); opacity: 0.55; } 50% { transform: scale(1.12); opacity: 0.95; } }
.radar {
  position: relative;
  flex: 0 0 auto;
  width: 46px;
  height: 46px;
  border-radius: 50%;
  border: 1px solid rgba(83, 230, 255, 0.2);
  background: radial-gradient(circle, rgba(83, 230, 255, 0.08), transparent 68%);
  overflow: hidden;
}
.radar::before, .radar::after {
  content: "";
  position: absolute;
  background: rgba(83, 230, 255, 0.16);
}
.radar::before { left: 50%; top: 8%; bottom: 8%; width: 1px; }
.radar::after { top: 50%; left: 8%; right: 8%; height: 1px; }
.radar i {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 50%;
  height: 50%;
  transform-origin: 0 0;
  background: conic-gradient(from 0deg, rgba(83, 230, 255, 0.34), transparent 70%);
  animation: radar-sweep 2.4s linear infinite;
}
.radar i:nth-child(2) { animation-delay: -0.8s; opacity: 0.5; }
.radar i:nth-child(3) { animation-delay: -1.6s; opacity: 0.3; }
@keyframes radar-sweep { to { transform: rotate(360deg); } }

.room-meta {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1px;
  margin: 14px 20px 0;
  border: 1px solid var(--line);
  border-radius: 10px;
  overflow: hidden;
  background: var(--line);
}
.room-meta div {
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 9px 11px;
  background: rgba(6, 10, 23, 0.9);
}
.room-meta span { font-family: var(--mono); font-size: 7px; letter-spacing: 0.16em; color: var(--dim); }
.room-meta strong { font-family: var(--mono); font-size: 14px; color: var(--ink); letter-spacing: 0.06em; }
.room-meta div:last-child strong { color: var(--gold); font-size: 11px; }

.primary-btn {
  position: relative;
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 15px 20px 0;
  min-height: 52px;
  padding: 0 20px;
  border: 0;
  border-radius: 11px;
  background: linear-gradient(100deg, #4ce2ff 0%, #6a9bff 48%, #b07bff 100%);
  color: #03101c;
  box-shadow: 0 10px 34px rgba(83, 230, 255, 0.22), inset 0 1px 0 rgba(255, 255, 255, 0.55);
  overflow: hidden;
  transition: transform 0.16s ease, box-shadow 0.16s ease, filter 0.16s ease;
}
.primary-btn::after {
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
  width: 42%;
  left: -60%;
  background: linear-gradient(100deg, transparent, rgba(255, 255, 255, 0.6), transparent);
  transform: skewX(-20deg);
  animation: btn-sheen 3.4s ease-in-out infinite;
}
@keyframes btn-sheen { 0%, 52% { left: -60%; } 82%, 100% { left: 130%; } }
.primary-btn:hover { transform: translateY(-2px); box-shadow: 0 16px 44px rgba(83, 230, 255, 0.34); filter: brightness(1.06); }
.primary-btn:active { transform: translateY(0); }
.btn-main { font-weight: 900; font-size: 16px; letter-spacing: 0.16em; }
.btn-sub { font-family: var(--mono); font-size: 8px; letter-spacing: 0.2em; opacity: 0.62; margin-left: auto; }
.btn-arrow { font-size: 13px; margin-left: 3px; }
.primary-btn.compact { margin: 0; min-height: 46px; min-width: 180px; justify-content: center; }
.primary-btn.compact .btn-main { font-size: 14px; }
.primary-btn.compact .btn-arrow { margin-left: auto; }
.hint { margin: 10px 20px 0; font-size: 10px; line-height: 1.6; color: var(--dim); letter-spacing: 0.03em; }

/* room list */
.room-list-panel { display: flex; flex-direction: column; }
.list-head, .room-row {
  display: grid;
  grid-template-columns: minmax(175px, 1.7fr) 0.52fr 0.58fr 0.76fr 66px;
  align-items: center;
  gap: 8px;
}
.list-head {
  margin: 14px 20px 0;
  padding: 0 10px 8px;
  border-bottom: 1px solid var(--line);
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.18em;
  color: var(--dim);
}
.room-list {
  flex: 1;
  min-height: 0;
  padding: 4px 12px;
  overflow-y: auto;
  scrollbar-width: thin;
  scrollbar-color: rgba(83, 230, 255, 0.25) transparent;
}
.room-list::-webkit-scrollbar { width: 4px; }
.room-list::-webkit-scrollbar-thumb { background: rgba(83, 230, 255, 0.22); border-radius: 9px; }
.room-row {
  position: relative;
  padding: 9px 10px;
  border-radius: 10px;
  border: 1px solid transparent;
  transition: 0.18s ease;
  animation: row-in 0.4s ease both;
}
@keyframes row-in { from { opacity: 0; transform: translateY(6px); } }
.room-row + .room-row { border-top: 1px solid rgba(126, 178, 255, 0.055); }
.room-row:hover { background: rgba(83, 230, 255, 0.045); border-color: rgba(83, 230, 255, 0.12); }
.room-row.mine { background: rgba(83, 230, 255, 0.055); border-color: rgba(83, 230, 255, 0.2); }
.room-row.invited { background: rgba(255, 79, 157, 0.07); border-color: rgba(255, 79, 157, 0.28); }
.row-host { display: flex; align-items: center; gap: 10px; min-width: 0; }
.row-avatar {
  flex: 0 0 auto;
  width: 33px;
  height: 33px;
  display: grid;
  place-items: center;
  border-radius: 8px;
  border: 1px solid color-mix(in srgb, var(--c) 40%, transparent);
  background: radial-gradient(circle at 30% 20%, color-mix(in srgb, var(--c) 24%, transparent), rgba(4, 8, 18, 0.9));
  color: var(--c);
  font-family: var(--mono);
  font-size: 11px;
  font-weight: 800;
  text-shadow: 0 0 8px var(--c);
}
.row-host div { min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.row-host strong { font-size: 12px; letter-spacing: 0.05em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.row-host small { font-family: var(--mono); font-size: 8px; letter-spacing: 0.08em; color: var(--dim); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.row-rank { font-family: var(--mono); font-size: 11px; font-weight: 700; color: var(--gold); }
.row-ping { display: flex; align-items: center; gap: 5px; font-family: var(--mono); font-size: 9px; color: var(--muted); }
.ping-bar { width: 19px; height: 3px; border-radius: 3px; background: rgba(255, 255, 255, 0.08); overflow: hidden; }
.ping-bar i { display: block; height: 100%; width: var(--p); background: var(--green); box-shadow: 0 0 6px var(--green); }
.ping-bar i.mid { background: var(--gold); box-shadow: 0 0 6px var(--gold); }
.ping-bar i.bad { background: var(--magenta); box-shadow: 0 0 6px var(--magenta); }
.row-state { font-family: var(--mono); font-size: 8px; letter-spacing: 0.08em; white-space: nowrap; }
.row-state.open { color: var(--green); }
.row-state.busy { color: var(--gold); }
.row-state.full { color: var(--magenta); }
.invite-btn {
  height: 27px;
  border: 1px solid rgba(83, 230, 255, 0.3);
  border-radius: 6px;
  background: rgba(83, 230, 255, 0.07);
  color: var(--cyan);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.12em;
  transition: 0.18s;
}
.invite-btn:hover { background: rgba(83, 230, 255, 0.16); box-shadow: 0 0 16px rgba(83, 230, 255, 0.18); }
.invite-btn:disabled { opacity: 0.3; cursor: not-allowed; box-shadow: none; }
.invite-btn.sent { border-color: rgba(255, 79, 157, 0.4); color: var(--magenta); background: rgba(255, 79, 157, 0.08); }
.list-foot {
  display: flex;
  gap: 9px;
  margin: 8px 20px 16px;
  padding-top: 11px;
  border-top: 1px solid var(--line);
  font-size: 9.5px;
  line-height: 1.6;
  color: var(--dim);
}
.foot-icon { color: var(--cyan); }

.lobby-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  flex: 0 0 auto;
  padding: 0 2px;
}
.rules-strip { display: flex; align-items: center; gap: 22px; flex-wrap: wrap; }
.rules-strip span {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.1em;
  color: var(--dim);
}
.rules-strip i { color: var(--cyan); font-style: normal; opacity: 0.7; }
.build-tag { font-family: var(--mono); font-size: 8px; letter-spacing: 0.14em; color: rgba(93, 113, 148, 0.7); white-space: nowrap; }

/* ============================================================
   DUEL
   ============================================================ */
.duel-topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  height: 48px;
  flex: 0 0 auto;
}
.ghost-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  height: 32px;
  padding: 0 13px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: rgba(8, 14, 30, 0.5);
  color: var(--muted);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.12em;
  transition: 0.18s;
}
.ghost-btn:hover { color: var(--cyan); border-color: var(--line-strong); background: rgba(83, 230, 255, 0.06); }
.back-btn span { font-size: 12px; }
.turn-chip {
  display: flex;
  align-items: center;
  gap: 9px;
  height: 34px;
  padding: 0 15px;
  border: 1px solid rgba(83, 230, 255, 0.25);
  border-radius: 999px;
  background: rgba(8, 18, 38, 0.7);
  box-shadow: 0 0 26px rgba(83, 230, 255, 0.08);
  transition: 0.3s;
}
.turn-chip.ai {
  border-color: rgba(255, 79, 157, 0.3);
  box-shadow: 0 0 26px rgba(255, 79, 157, 0.1);
}
.turn-dot { width: 5px; height: 5px; border-radius: 50%; background: var(--cyan); box-shadow: 0 0 9px var(--cyan); animation: pulse 1.4s infinite; }
.turn-chip.ai .turn-dot { background: var(--magenta); box-shadow: 0 0 9px var(--magenta); }
.turn-chip b { font-size: 10px; letter-spacing: 0.18em; color: var(--cyan); }
.turn-chip.ai b { color: var(--magenta); }
.turn-chip small { font-family: var(--mono); font-size: 8px; letter-spacing: 0.12em; color: var(--dim); border-left: 1px solid var(--line); padding-left: 9px; }
.duel-top-right { display: flex; align-items: center; gap: 9px; }
.mini-stat { font-family: var(--mono); font-size: 8px; letter-spacing: 0.12em; color: var(--dim); }
.mini-stat b { color: var(--ink); }

.duel-layout {
  flex: 1;
  min-height: 0;
  display: flex;
  gap: 12px;
  justify-content: center;
  padding-bottom: 2px;
}
.arena-column {
  flex: 1;
  max-width: 1080px;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 7px;
}

/* HUD */
.hud {
  position: relative;
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 8px 12px;
  border: 1px solid var(--line);
  border-radius: 11px;
  background: linear-gradient(100deg, rgba(16, 26, 54, 0.72), rgba(5, 9, 21, 0.72));
  box-shadow: inset 0 1px 0 rgba(180, 220, 255, 0.05);
  flex: 0 0 auto;
  z-index: 3;
}
.opponent-hud { border-color: rgba(255, 79, 157, 0.18); }
.player-hud { border-color: rgba(83, 230, 255, 0.22); }
.ai-avatar, .you-avatar { width: 38px; height: 38px; border-radius: 9px; font-size: 12px; }
.hud-id { display: flex; flex-direction: column; gap: 1px; min-width: 88px; max-width: 145px; }
.hud-label { font-family: var(--mono); font-size: 7px; letter-spacing: 0.18em; color: var(--dim); }
.hud-id strong { font-size: 13px; letter-spacing: 0.05em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.hud-id small { font-family: var(--mono); font-size: 7.5px; letter-spacing: 0.1em; color: var(--gold); }
.lp-block { flex: 1; min-width: 130px; display: flex; align-items: center; gap: 10px; }
.lp-bar {
  position: relative;
  flex: 1;
  height: 14px;
  border-radius: 4px;
  background: rgba(3, 7, 16, 0.9);
  border: 1px solid rgba(126, 178, 255, 0.14);
  overflow: hidden;
}
.lp-bar i {
  position: absolute;
  inset: 1px;
  width: 100%;
  border-radius: 3px;
  background: linear-gradient(90deg, #36d9ff, #5d8bff 65%, #a37bff);
  box-shadow: 0 0 18px rgba(83, 230, 255, 0.45);
  transition: width 0.7s cubic-bezier(0.22, 1, 0.36, 1);
  transform-origin: left;
}
.opponent-hud .lp-bar i { background: linear-gradient(90deg, #ff4f9d, #ff7857 70%, #ffcc66); box-shadow: 0 0 18px rgba(255, 79, 157, 0.4); }
.lp-bar i.low { animation: lp-danger 1s ease-in-out infinite; }
@keyframes lp-danger { 0%, 100% { filter: brightness(1); } 50% { filter: brightness(1.6); } }
.lp-scan {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 26px;
  left: -30px;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.34), transparent);
  animation: lp-scan 3.2s ease-in-out infinite;
}
@keyframes lp-scan { 0%, 55% { left: -30px; } 100% { left: 105%; } }
.lp-num { display: flex; align-items: baseline; gap: 3px; min-width: 58px; justify-content: flex-end; }
.lp-num span { font-family: var(--mono); font-size: 17px; font-weight: 800; letter-spacing: 0.03em; color: var(--ink); }
.opponent-hud .lp-num span { color: #ffd1e3; }
.lp-num small { font-family: var(--mono); font-size: 7px; color: var(--dim); letter-spacing: 0.1em; }
.hud-counters { display: flex; gap: 11px; }
.hud-counters span { font-family: var(--mono); font-size: 7.5px; letter-spacing: 0.1em; color: var(--dim); white-space: nowrap; }
.hud-counters b { color: var(--ink); font-size: 10px; }
.ai-state {
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.14em;
  color: var(--dim);
  border: 1px solid var(--line);
  border-radius: 4px;
  padding: 3px 6px;
  white-space: nowrap;
}
.ai-state.thinking { color: var(--magenta); border-color: rgba(255, 79, 157, 0.3); animation: pulse 1.1s infinite; }
.energy-block {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 3px 9px;
  border-left: 1px solid var(--line);
  border-right: 1px solid var(--line);
  min-width: 122px;
}
.energy-pips { display: flex; gap: 3px; }
.energy-pips i {
  width: 7px;
  height: 12px;
  border-radius: 2px;
  background: rgba(126, 178, 255, 0.12);
  border: 1px solid rgba(126, 178, 255, 0.2);
  transition: 0.25s;
}
.energy-pips i.on {
  background: linear-gradient(to top, #ffb84d, #ffe89a);
  border-color: rgba(255, 204, 102, 0.8);
  box-shadow: 0 0 8px rgba(255, 204, 102, 0.6);
  animation: energy-pulse 1.8s ease-in-out infinite;
}
@keyframes energy-pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.65; } }
.energy-block b { font-family: var(--mono); font-size: 14px; color: var(--gold); }
.end-turn-btn {
  margin-left: auto;
  display: flex;
  align-items: center;
  gap: 8px;
  height: 34px;
  padding: 0 13px;
  border: 1px solid rgba(83, 230, 255, 0.4);
  border-radius: 8px;
  background: linear-gradient(100deg, rgba(83, 230, 255, 0.18), rgba(154, 123, 255, 0.14));
  color: var(--cyan);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.12em;
  transition: 0.18s;
  white-space: nowrap;
}
.end-turn-btn small { color: var(--dim); border: 1px solid var(--line); border-radius: 3px; padding: 1px 4px; font-size: 7px; }
.end-turn-btn:hover { background: rgba(83, 230, 255, 0.28); box-shadow: 0 0 20px rgba(83, 230, 255, 0.2); }
.end-turn-btn:disabled { opacity: 0.32; cursor: not-allowed; box-shadow: none; }

/* arena */
.arena {
  position: relative;
  flex: 1;
  min-height: 0;
  padding: 20px 10px 18px;
  border: 1px solid rgba(126, 178, 255, 0.18);
  border-radius: 14px;
  background:
    linear-gradient(180deg, rgba(255, 79, 157, 0.035), transparent 42%, transparent 58%, rgba(83, 230, 255, 0.045)),
    radial-gradient(ellipse 70% 60% at 50% 50%, rgba(22, 38, 80, 0.28), transparent 72%),
    rgba(3, 6, 15, 0.7);
  box-shadow: inset 0 0 60px rgba(0, 0, 0, 0.55), 0 20px 60px rgba(0, 0, 0, 0.3);
  overflow: hidden;
}
.arena::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background-image: linear-gradient(rgba(83, 230, 255, 0.035) 1px, transparent 1px);
  background-size: 100% 12px;
  animation: scan-move 9s linear infinite;
  opacity: 0.6;
}
@keyframes scan-move { to { background-position: 0 120px; } }
.arena-territory {
  position: absolute;
  left: 13px;
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.28em;
  color: rgba(255, 79, 157, 0.5);
  z-index: 2;
  pointer-events: none;
}
.arena-territory.enemy { top: 5px; }
.arena-territory.player { bottom: 4px; color: rgba(83, 230, 255, 0.5); }
.zone-grid {
  position: relative;
  z-index: 1;
  height: 100%;
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  grid-template-rows: repeat(4, minmax(0, 1fr));
  gap: 5px;
}
.zone {
  position: relative;
  border: 1px solid rgba(126, 178, 255, 0.11);
  border-radius: 7px;
  background:
    linear-gradient(145deg, rgba(14, 22, 44, 0.55), rgba(5, 8, 18, 0.6));
  transition: border-color 0.16s, background 0.16s, box-shadow 0.16s;
  min-height: 0;
  overflow: visible;
}
.zone[data-owner="ai"][data-row="1"], .zone[data-owner="ai"][data-row="0"] {
  background: linear-gradient(145deg, rgba(52, 15, 38, 0.36), rgba(9, 7, 18, 0.6));
}
.zone[data-owner="player"][data-row="2"], .zone[data-owner="player"][data-row="3"] {
  background: linear-gradient(145deg, rgba(9, 29, 48, 0.42), rgba(5, 9, 19, 0.62));
}
.zone::after {
  content: "";
  position: absolute;
  inset: 3px;
  border: 1px dashed rgba(126, 178, 255, 0.045);
  border-radius: 4px;
  pointer-events: none;
}
.zone-tag {
  position: absolute;
  top: 3px;
  left: 5px;
  font-family: var(--mono);
  font-size: 6.5px;
  letter-spacing: 0.08em;
  color: rgba(126, 178, 255, 0.24);
  z-index: 2;
  pointer-events: none;
}
.zone.col-hot { border-color: rgba(83, 230, 255, 0.3); background: rgba(83, 230, 255, 0.06); }
.zone.summonable {
  cursor: pointer;
  border-color: rgba(83, 230, 255, 0.42);
  background: rgba(83, 230, 255, 0.075);
  box-shadow: inset 0 0 22px rgba(83, 230, 255, 0.1);
  animation: summon-pulse 1.5s ease-in-out infinite;
}
@keyframes summon-pulse {
  0%, 100% { box-shadow: inset 0 0 16px rgba(83, 230, 255, 0.06); }
  50% { box-shadow: inset 0 0 30px rgba(83, 230, 255, 0.2); }
}
.zone.summonable:hover { background: rgba(83, 230, 255, 0.15); border-color: var(--cyan); }
.zone.targetable { cursor: crosshair; border-color: rgba(255, 79, 157, 0.55); box-shadow: inset 0 0 26px rgba(255, 79, 157, 0.12); }
.zone.targetable:hover { background: rgba(255, 79, 157, 0.16); }
.zone.targetable.lethal { animation: lethal-pulse 0.9s ease-in-out infinite; }
@keyframes lethal-pulse {
  0%, 100% { box-shadow: inset 0 0 24px rgba(255, 79, 157, 0.12); }
  50% { box-shadow: inset 0 0 40px rgba(255, 60, 60, 0.3); }
}
.zone.targetable .target-tag {
  position: absolute;
  right: 4px;
  bottom: 4px;
  z-index: 4;
  font-family: var(--mono);
  font-size: 6px;
  letter-spacing: 0.1em;
  padding: 1px 4px;
  border-radius: 3px;
  color: #1a0410;
  background: linear-gradient(90deg, #ff7aa8, #ffcc66);
  box-shadow: 0 0 10px rgba(255, 79, 157, 0.5);
}
.arena-center-line {
  position: absolute;
  left: 8px;
  right: 8px;
  top: 50%;
  height: 1px;
  transform: translateY(-50%);
  background: linear-gradient(90deg, transparent, rgba(126, 198, 255, 0.4), rgba(255, 79, 157, 0.35), transparent);
  z-index: 3;
  pointer-events: none;
}
.arena-center-line span {
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  padding: 2px 10px;
  background: #050a15;
  border: 1px solid rgba(126, 178, 255, 0.2);
  border-radius: 999px;
  font-family: var(--mono);
  font-size: 6px;
  letter-spacing: 0.3em;
  color: var(--dim);
  white-space: nowrap;
}

/* unit cards */
.unit {
  position: absolute;
  inset: 2px;
  z-index: 2;
  display: flex;
  flex-direction: column;
  padding: 5px 6px 4px;
  border-radius: 6px;
  border: 1px solid color-mix(in srgb, var(--c) 58%, transparent);
  background:
    radial-gradient(circle at 28% 16%, color-mix(in srgb, var(--c) 30%, transparent), transparent 54%),
    linear-gradient(155deg, color-mix(in srgb, var(--c) 20%, #0a1224), #060a16 74%);
  box-shadow:
    0 0 16px color-mix(in srgb, var(--c) 22%, transparent),
    inset 0 0 18px color-mix(in srgb, var(--c) 10%, transparent);
  overflow: hidden;
  animation: unit-float 4.4s ease-in-out infinite;
  animation-delay: calc(var(--i, 0) * -0.53s);
  transform-origin: 50% 80%;
  cursor: pointer;
  user-select: none;
}
@keyframes unit-float {
  0%, 100% { translate: 0 0; }
  50% { translate: 0 -2px; }
}
.unit::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(115deg, transparent 20%, rgba(255, 255, 255, 0.14) 45%, transparent 62%);
  transform: translateX(-130%);
  animation: holo-sweep 4.8s ease-in-out infinite;
  animation-delay: calc(var(--i, 0) * -0.37s);
  pointer-events: none;
}
@keyframes holo-sweep { 0%, 58% { transform: translateX(-130%); } 88%, 100% { transform: translateX(130%); } }
.unit::after {
  content: "";
  position: absolute;
  inset: 2px;
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 4px;
  pointer-events: none;
}
.unit.opponent { --glow: rgba(255, 79, 157, 0.5); }
.unit.player { --glow: rgba(83, 230, 255, 0.45); }
.unit .u-cost {
  position: absolute;
  top: 3px;
  left: 4px;
  z-index: 2;
  width: 14px;
  height: 14px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: #050a15;
  border: 1px solid color-mix(in srgb, var(--c) 70%, transparent);
  color: var(--c);
  font-family: var(--mono);
  font-size: 7px;
  font-weight: 800;
}
.unit .u-kw {
  position: absolute;
  top: 3px;
  right: 4px;
  z-index: 2;
  font-family: var(--mono);
  font-size: 5.5px;
  letter-spacing: 0.06em;
  color: var(--c);
  opacity: 0.9;
  text-shadow: 0 0 6px var(--c);
  max-width: 58%;
  text-align: right;
  overflow: hidden;
  white-space: nowrap;
}
.unit .u-art {
  flex: 1;
  min-height: 0;
  display: grid;
  place-items: center;
  margin: 1px -2px 0;
  background: radial-gradient(circle, color-mix(in srgb, var(--c) 18%, transparent), transparent 68%);
}
.unit .u-glyph {
  font-size: clamp(17px, 3.1vh, 34px);
  line-height: 1;
  color: var(--c);
  text-shadow: 0 0 14px var(--c), 0 0 34px color-mix(in srgb, var(--c) 50%, transparent);
  animation: glyph-breathe 3.6s ease-in-out infinite;
}
@keyframes glyph-breathe {
  0%, 100% { transform: scale(1) rotate(-2deg); opacity: 0.85; }
  50% { transform: scale(1.1) rotate(2deg); opacity: 1; }
}
.unit .u-name {
  font-size: clamp(7px, 0.92vh, 9.5px);
  font-weight: 700;
  letter-spacing: 0.03em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  text-align: center;
  color: #eaf3ff;
  z-index: 2;
}
.unit .u-stats {
  display: flex;
  justify-content: space-between;
  gap: 3px;
  margin-top: 2px;
  font-family: var(--mono);
  font-size: clamp(7px, 0.92vh, 10px);
  z-index: 2;
}
.unit .u-stats b { color: var(--c); text-shadow: 0 0 8px color-mix(in srgb, var(--c) 60%, transparent); }
.unit .u-stats b.buffed { color: var(--gold); text-shadow: 0 0 8px rgba(255, 204, 102, 0.7); }
.unit .u-stats span { color: #a8bdd9; }
.unit.player.summmoned { animation: summon-drop 0.5s cubic-bezier(0.16, 1, 0.3, 1), unit-float 4.4s ease-in-out 0.5s infinite; }
@keyframes summon-drop {
  0% { opacity: 0; transform: scale(0.5) translateY(-26px); filter: brightness(3); }
  60% { opacity: 1; transform: scale(1.04) translateY(0); }
  100% { transform: scale(1); filter: brightness(1); }
}
.unit.used { filter: saturate(0.5) brightness(0.72); }
.unit.used::after { border-color: rgba(255, 255, 255, 0.04); }
.unit.used .u-glyph { animation: none; opacity: 0.6; }
.unit.selected {
  border-color: var(--gold);
  box-shadow: 0 0 0 1px var(--gold), 0 0 26px rgba(255, 204, 102, 0.4), inset 0 0 20px rgba(255, 204, 102, 0.12);
  z-index: 4;
  translate: 0 -3px;
  animation: none;
}
.unit.ready { box-shadow: 0 0 0 1px color-mix(in srgb, var(--c) 30%, transparent), 0 0 18px color-mix(in srgb, var(--c) 18%, transparent); }
.unit.attacking { animation: unit-lunge 0.42s cubic-bezier(0.3, 0, 0.3, 1); z-index: 6; }
.unit.attacking.ai { animation-name: unit-lunge-ai; }
@keyframes unit-lunge {
  0% { transform: translateY(0) scale(1); }
  38% { transform: translateY(-14px) scale(1.06); filter: brightness(1.6); }
  100% { transform: translateY(0) scale(1); }
}
@keyframes unit-lunge-ai {
  0% { transform: translateY(0) scale(1); }
  38% { transform: translateY(14px) scale(1.06); filter: brightness(1.6); }
  100% { transform: translateY(0) scale(1); }
}
.unit.destroyed { animation: unit-shatter 0.42s cubic-bezier(0.4, 0, 0.8, 0.4) forwards; z-index: 7; }
@keyframes unit-shatter {
  0% { opacity: 1; transform: scale(1); filter: brightness(2.4); }
  45% { opacity: 0.9; transform: scale(1.08) rotate(-2deg); filter: brightness(3) saturate(0.3); }
  100% { opacity: 0; transform: scale(0.2) rotate(9deg); filter: brightness(4) saturate(0); }
}

/* fx layer */
.fx-layer { position: absolute; inset: 0; z-index: 8; pointer-events: none; overflow: hidden; }
.beam {
  position: fixed;
  z-index: 90;
  height: 3px;
  transform-origin: 0 50%;
  border-radius: 999px;
  background: linear-gradient(90deg, transparent, var(--c) 20%, #fff 52%, var(--c) 78%, transparent);
  box-shadow: 0 0 14px var(--c), 0 0 32px var(--c);
  pointer-events: none;
  animation: beam-fire 0.4s ease-out forwards;
}
@keyframes beam-fire {
  0% { transform: scaleX(0) rotate(var(--r)); opacity: 0; }
  22% { transform: scaleX(1) rotate(var(--r)); opacity: 1; }
  70% { opacity: 1; }
  100% { transform: scaleX(1) rotate(var(--r)); opacity: 0; }
}
.impact {
  position: fixed;
  z-index: 91;
  width: 14px;
  height: 14px;
  border: 2px solid var(--c);
  border-radius: 50%;
  box-shadow: 0 0 22px var(--c), inset 0 0 14px var(--c);
  transform: translate(-50%, -50%);
  animation: impact-ring 0.5s ease-out forwards;
  pointer-events: none;
}
@keyframes impact-ring {
  0% { opacity: 1; transform: translate(-50%, -50%) scale(0.3); }
  100% { opacity: 0; transform: translate(-50%, -50%) scale(4.2); }
}
.float-num {
  position: fixed;
  z-index: 95;
  transform: translate(-50%, -50%);
  font-family: var(--mono);
  font-size: clamp(16px, 2vw, 26px);
  font-weight: 900;
  letter-spacing: 0.02em;
  color: #fff;
  text-shadow: 0 0 10px var(--c), 0 0 26px var(--c);
  pointer-events: none;
  animation: float-up 1s cubic-bezier(0.2, 0.8, 0.3, 1) forwards;
  white-space: nowrap;
}
.float-num.bad { color: #ff8fb8; }
.float-num.heal { color: var(--green); }
@keyframes float-up {
  0% { opacity: 0; transform: translate(-50%, -30%) scale(0.6); }
  18% { opacity: 1; transform: translate(-50%, -60%) scale(1.1); }
  100% { opacity: 0; transform: translate(-50%, -180%) scale(1); }
}
.shake { animation: screen-shake 0.3s ease-in-out; }
@keyframes screen-shake {
  0%, 100% { transform: translate(0, 0); }
  20% { transform: translate(-4px, 2px); }
  40% { transform: translate(4px, -2px); }
  60% { transform: translate(-2px, -1px); }
  80% { transform: translate(2px, 1px); }
}

/* hand */
.hand-wrap {
  flex: 0 0 auto;
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 0 2px;
}
.hand-head { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.hand-tip { font-size: 8.5px; color: var(--dim); letter-spacing: 0.02em; }
.hand {
  display: flex;
  align-items: flex-end;
  justify-content: center;
  gap: clamp(4px, 0.6vw, 9px);
  min-height: 122px;
  padding: 6px 4px 2px;
  overflow-x: auto;
  overflow-y: hidden;
  scrollbar-width: thin;
  scrollbar-color: rgba(83, 230, 255, 0.2) transparent;
}
.hand::-webkit-scrollbar { height: 3px; }
.hand::-webkit-scrollbar-thumb { background: rgba(83, 230, 255, 0.2); border-radius: 9px; }
.hand-card {
  position: relative;
  flex: 0 0 auto;
  width: clamp(86px, 8.2vw, 112px);
  aspect-ratio: 0.7;
  padding: 0;
  border: 1px solid color-mix(in srgb, var(--c) 42%, transparent);
  border-radius: 9px;
  background:
    radial-gradient(circle at 50% 24%, color-mix(in srgb, var(--c) 26%, transparent), transparent 55%),
    linear-gradient(160deg, color-mix(in srgb, var(--c) 13%, #0b1326), #050812 72%);
  box-shadow: 0 10px 26px rgba(0, 0, 0, 0.5), inset 0 0 18px color-mix(in srgb, var(--c) 8%, transparent);
  overflow: hidden;
  transition: transform 0.18s cubic-bezier(0.2, 0.8, 0.3, 1.2), box-shadow 0.18s, border-color 0.18s, opacity 0.18s, filter 0.18s;
  text-align: left;
  animation: card-in 0.4s cubic-bezier(0.16, 1, 0.3, 1) both;
}
@keyframes card-in {
  from { opacity: 0; transform: translateY(26px) rotate(-3deg); }
}
.hand-card::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(115deg, transparent 25%, rgba(255, 255, 255, 0.18) 48%, transparent 65%);
  transform: translateX(-130%);
  animation: holo-sweep 5s ease-in-out infinite;
  animation-delay: calc(var(--i, 0) * -0.6s);
  pointer-events: none;
}
.hand-card::after {
  content: "";
  position: absolute;
  inset: 4px;
  border: 1px solid rgba(255, 255, 255, 0.07);
  border-radius: 6px;
  pointer-events: none;
}
.hand-card:hover { transform: translateY(-12px) scale(1.03); box-shadow: 0 20px 36px rgba(0, 0, 0, 0.58), 0 0 26px color-mix(in srgb, var(--c) 34%, transparent); z-index: 5; }
.hand-card.selected {
  transform: translateY(-16px) scale(1.05);
  border-color: var(--gold);
  box-shadow: 0 0 0 1px var(--gold), 0 18px 40px rgba(0, 0, 0, 0.6), 0 0 34px rgba(255, 204, 102, 0.36);
  z-index: 6;
}
.hand-card.unaffordable { opacity: 0.44; filter: saturate(0.4); cursor: not-allowed; }
.hand-card.unaffordable:hover { transform: translateY(-3px); box-shadow: 0 10px 26px rgba(0, 0, 0, 0.5); }
.hand-card .hc-cost {
  position: absolute;
  top: 5px;
  left: 5px;
  z-index: 3;
  width: 21px;
  height: 21px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: rgba(3, 8, 18, 0.92);
  border: 1px solid color-mix(in srgb, var(--c) 80%, transparent);
  color: var(--c);
  font-family: var(--mono);
  font-size: 10px;
  font-weight: 800;
  box-shadow: 0 0 12px color-mix(in srgb, var(--c) 30%, transparent);
}
.hand-card .hc-faction {
  position: absolute;
  top: 7px;
  right: 6px;
  z-index: 3;
  font-family: var(--mono);
  font-size: 5.5px;
  letter-spacing: 0.14em;
  color: var(--c);
  opacity: 0.8;
}
.hand-card .hc-art {
  position: absolute;
  top: 20%;
  left: 0;
  right: 0;
  height: 44%;
  display: grid;
  place-items: center;
  background: radial-gradient(circle, color-mix(in srgb, var(--c) 22%, transparent), transparent 68%);
}
.hand-card .hc-glyph {
  font-size: clamp(28px, 3.2vw, 42px);
  color: var(--c);
  text-shadow: 0 0 16px var(--c), 0 0 42px color-mix(in srgb, var(--c) 55%, transparent);
  animation: glyph-breathe 3.8s ease-in-out infinite;
}
.hand-card .hc-name {
  position: absolute;
  left: 6px;
  right: 6px;
  top: 64%;
  z-index: 3;
  font-size: clamp(8px, 0.85vw, 10.5px);
  font-weight: 800;
  text-align: center;
  letter-spacing: 0.02em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.hand-card .hc-stats {
  position: absolute;
  left: 7px;
  right: 7px;
  top: 76%;
  z-index: 3;
  display: flex;
  justify-content: space-between;
  font-family: var(--mono);
  font-size: clamp(8px, 0.76vw, 9.5px);
  color: #b9cbe6;
}
.hand-card .hc-stats b { color: var(--c); }
.hand-card .hc-keywords {
  position: absolute;
  left: 5px;
  right: 5px;
  bottom: 5px;
  z-index: 3;
  display: flex;
  gap: 3px;
  flex-wrap: wrap;
  justify-content: center;
}
.hand-card .hc-keywords span {
  font-family: var(--mono);
  font-size: 5.5px;
  letter-spacing: 0.05em;
  padding: 1px 3px;
  border-radius: 2px;
  color: var(--c);
  background: color-mix(in srgb, var(--c) 12%, transparent);
  border: 1px solid color-mix(in srgb, var(--c) 26%, transparent);
  white-space: nowrap;
}
.hand-empty { font-family: var(--mono); font-size: 9px; letter-spacing: 0.15em; color: var(--dim); padding: 40px 0; }

/* rail */
.duel-rail {
  width: 238px;
  flex: 0 0 238px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-height: 0;
}
.rail-card {
  border: 1px solid var(--line);
  border-radius: 11px;
  background: rgba(8, 14, 30, 0.62);
  backdrop-filter: blur(12px);
  padding: 11px 12px;
}
.inspect-card { min-height: 150px; }
.inspect-body { margin-top: 8px; }
.inspect-empty { font-size: 9.5px; line-height: 1.7; color: var(--dim); }
.inspect-name { font-size: 13px; font-weight: 800; margin-bottom: 2px; }
.inspect-meta { display: flex; gap: 8px; align-items: center; font-family: var(--mono); font-size: 8px; color: var(--muted); margin-bottom: 7px; }
.inspect-meta b { color: var(--c); }
.inspect-text { font-size: 9.5px; line-height: 1.65; color: var(--muted); }
.inspect-kws { display: flex; gap: 4px; flex-wrap: wrap; margin-top: 7px; }
.inspect-kws span { font-family: var(--mono); font-size: 6.5px; letter-spacing: 0.06em; padding: 2px 5px; border-radius: 3px; border: 1px solid color-mix(in srgb, var(--c) 32%, transparent); color: var(--c); }
.inspect-stats { display: flex; gap: 12px; margin-top: 8px; font-family: var(--mono); font-size: 15px; }
.inspect-stats b { color: var(--c); }
.inspect-stats small { font-size: 6px; color: var(--dim); display: block; letter-spacing: 0.12em; }
.log-card { flex: 1; min-height: 0; display: flex; flex-direction: column; }
.rail-head { display: flex; align-items: center; justify-content: space-between; }
.log-live { display: inline-flex; align-items: center; gap: 4px; font-family: var(--mono); font-size: 7px; letter-spacing: 0.14em; color: var(--dim); }
.log-live i { background: var(--magenta); box-shadow: 0 0 8px var(--magenta); }
.duel-log {
  margin-top: 8px;
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 6px;
  scrollbar-width: thin;
  scrollbar-color: rgba(83, 230, 255, 0.18) transparent;
}
.duel-log::-webkit-scrollbar { width: 3px; }
.duel-log::-webkit-scrollbar-thumb { background: rgba(83, 230, 255, 0.18); }
.log-line {
  display: flex;
  gap: 6px;
  font-size: 9px;
  line-height: 1.5;
  color: var(--muted);
  animation: row-in 0.3s ease both;
}
.log-line i { font-family: var(--mono); font-size: 7px; color: var(--dim); font-style: normal; padding-top: 1px; flex: 0 0 auto; }
.log-line.hot { color: #ffc7dd; }
.log-line.good { color: #9cf2cf; }
.log-line.sys { color: var(--cyan); }
.key-card { flex: 0 0 auto; }
.key-list { display: flex; flex-direction: column; gap: 4px; margin-top: 7px; }
.key-list span { font-size: 8px; line-height: 1.45; color: var(--dim); }
.key-list b { font-family: var(--mono); font-size: 7px; letter-spacing: 0.08em; color: var(--gold); margin-right: 4px; }

/* banner */
.banner {
  position: fixed;
  left: 50%;
  top: 46%;
  z-index: 80;
  transform: translate(-50%, -50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 5px;
  padding: 18px 54px;
  pointer-events: none;
  opacity: 0;
  text-align: center;
  background: linear-gradient(90deg, transparent, rgba(5, 10, 22, 0.92) 20%, rgba(5, 10, 22, 0.92) 80%, transparent);
  border-top: 1px solid rgba(83, 230, 255, 0.18);
  border-bottom: 1px solid rgba(83, 230, 255, 0.18);
  white-space: nowrap;
}
.banner.show { animation: banner-in 1.5s cubic-bezier(0.2, 0.8, 0.2, 1) forwards; }
.banner.ai { border-color: rgba(255, 79, 157, 0.22); }
@keyframes banner-in {
  0% { opacity: 0; transform: translate(-50%, -50%) scale(1.14); filter: blur(6px); }
  16% { opacity: 1; transform: translate(-50%, -50%) scale(1); filter: blur(0); }
  78% { opacity: 1; }
  100% { opacity: 0; transform: translate(-50%, -50%) scale(0.99); }
}
.banner-kicker { font-family: var(--mono); font-size: 8px; letter-spacing: 0.34em; color: var(--cyan); }
.banner.ai .banner-kicker { color: var(--magenta); }
.banner strong {
  font-size: clamp(30px, 4.6vw, 58px);
  font-weight: 900;
  letter-spacing: 0.12em;
  line-height: 1;
  background: linear-gradient(100deg, #fff, #8fe9ff 55%, #b79bff);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  filter: drop-shadow(0 0 24px rgba(83, 230, 255, 0.35));
}
.banner.ai strong { background: linear-gradient(100deg, #fff, #ffa2c9 55%, #ffcc66); -webkit-background-clip: text; background-clip: text; filter: drop-shadow(0 0 24px rgba(255, 79, 157, 0.35)); }
.banner small { font-family: var(--mono); font-size: 8px; letter-spacing: 0.2em; color: var(--muted); }

/* toast */
.toast {
  position: fixed;
  left: 50%;
  bottom: 26px;
  z-index: 120;
  transform: translate(-50%, 20px);
  padding: 11px 20px;
  border: 1px solid rgba(83, 230, 255, 0.4);
  border-radius: 999px;
  background: rgba(5, 12, 26, 0.94);
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.6), 0 0 26px rgba(83, 230, 255, 0.12);
  font-family: var(--mono);
  font-size: 9.5px;
  letter-spacing: 0.08em;
  color: #cfeaff;
  opacity: 0;
  pointer-events: none;
  transition: 0.28s cubic-bezier(0.2, 0.8, 0.3, 1.1);
  max-width: min(90vw, 520px);
  text-align: center;
  backdrop-filter: blur(12px);
}
.toast.show { opacity: 1; transform: translate(-50%, 0); }
.toast.warn { border-color: rgba(255, 79, 157, 0.45); color: #ffd0e2; }

/* result */
.result {
  position: fixed;
  inset: 0;
  z-index: 110;
  display: grid;
  place-items: center;
  padding: 20px;
  background: radial-gradient(circle at 50% 45%, rgba(9, 22, 46, 0.7), rgba(2, 4, 10, 0.9));
  backdrop-filter: blur(9px);
  transition: opacity 0.35s;
}
.result.hidden { opacity: 0; pointer-events: none; }
.result-card {
  position: relative;
  width: min(520px, 94vw);
  padding: 30px 34px 28px;
  border: 1px solid rgba(83, 230, 255, 0.28);
  border-radius: 18px;
  background:
    radial-gradient(ellipse 80% 50% at 50% 0%, rgba(83, 230, 255, 0.1), transparent 70%),
    linear-gradient(160deg, rgba(18, 30, 62, 0.92), rgba(5, 9, 20, 0.96));
  box-shadow: 0 38px 100px rgba(0, 0, 0, 0.7), inset 0 1px 0 rgba(180, 220, 255, 0.12);
  text-align: center;
  animation: result-in 0.55s cubic-bezier(0.16, 1, 0.3, 1) both;
  overflow: hidden;
}
@keyframes result-in { from { opacity: 0; transform: translateY(24px) scale(0.96); } }
.result-card::before {
  content: "";
  position: absolute;
  left: 15%;
  right: 15%;
  top: 0;
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--cyan), var(--violet), transparent);
}
.result.defeat .result-card { border-color: rgba(255, 79, 157, 0.3); }
.result.defeat .result-card::before { background: linear-gradient(90deg, transparent, var(--magenta), var(--gold), transparent); }
.result-kicker { font-family: var(--mono); font-size: 8px; letter-spacing: 0.34em; color: var(--dim); }
.result-card h2 {
  margin: 9px 0 4px;
  font-size: clamp(44px, 7vw, 76px);
  font-weight: 900;
  letter-spacing: 0.1em;
  line-height: 1;
  background: linear-gradient(100deg, #fff, #8fe9ff 45%, #b79bff 75%, #ff9bc5);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  filter: drop-shadow(0 0 30px rgba(83, 230, 255, 0.35));
}
.result.defeat .result-card h2 { background: linear-gradient(100deg, #fff, #ff92bc 48%, #ffb35c); -webkit-background-clip: text; background-clip: text; filter: drop-shadow(0 0 30px rgba(255, 79, 157, 0.32)); }
.result-sub { font-family: var(--mono); font-size: 9px; letter-spacing: 0.22em; color: var(--muted); }
.result-lp { display: flex; align-items: center; justify-content: center; gap: 18px; margin: 20px 0 6px; font-family: var(--mono); font-size: 8px; letter-spacing: 0.12em; color: var(--dim); }
.result-lp span { display: flex; flex-direction: column; gap: 3px; }
.result-lp b { font-size: 22px; color: var(--ink); letter-spacing: 0.03em; }
.result-lp span:last-child b { color: var(--magenta); }
.result-lp i { width: 1px; height: 34px; background: var(--line); }
.result-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1px; margin: 18px 0 22px; border: 1px solid var(--line); border-radius: 10px; overflow: hidden; background: var(--line); }
.result-stats div { display: flex; flex-direction: column; gap: 5px; padding: 11px 8px; background: rgba(4, 8, 18, 0.9); }
.result-stats span { font-family: var(--mono); font-size: 6.5px; letter-spacing: 0.16em; color: var(--dim); }
.result-stats b { font-family: var(--mono); font-size: 18px; color: var(--cyan); }
.result-actions { display: flex; align-items: center; justify-content: center; gap: 10px; }
.result-actions .ghost-btn { height: 46px; }

/* boot */
.boot {
  position: fixed;
  inset: 0;
  z-index: 200;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  background: #04060d;
  transition: opacity 0.5s, visibility 0.5s;
}
.boot.done { opacity: 0; visibility: hidden; }
.boot-mark { position: relative; width: 70px; height: 76px; margin-bottom: 8px; }
.boot-mark i {
  position: absolute;
  inset: 6px 16px;
  border: 2px solid var(--cyan);
  border-radius: 8px;
  transform: rotate(-12deg);
  box-shadow: 0 0 30px rgba(83, 230, 255, 0.4);
  animation: mark-float 2.4s ease-in-out infinite;
}
.boot-mark i:last-child { border-color: var(--magenta); transform: rotate(12deg); box-shadow: 0 0 30px rgba(255, 79, 157, 0.35); animation-name: mark-float-b; }
.boot-logo { font-size: 42px; font-weight: 900; letter-spacing: 0.1em; background: linear-gradient(100deg, #fff, #8fe9ff, #ff9bc5); -webkit-background-clip: text; background-clip: text; color: transparent; }
.boot-logo span { -webkit-text-stroke: 1px rgba(255, 255, 255, 0.6); color: transparent; font-size: 0.7em; }
.boot p { font-family: var(--mono); font-size: 8px; letter-spacing: 0.4em; color: var(--dim); }
.boot-bar { width: 180px; height: 2px; margin-top: 18px; background: rgba(126, 178, 255, 0.12); overflow: hidden; }
.boot-bar i { display: block; height: 100%; width: 40%; background: linear-gradient(90deg, transparent, var(--cyan), transparent); animation: boot-load 1.1s ease-in-out infinite; }
@keyframes boot-load { from { transform: translateX(-120%); } to { transform: translateX(350%); } }
.boot small { font-family: var(--mono); font-size: 7px; letter-spacing: 0.22em; color: var(--dim); }
.noscript { position: fixed; inset: 0; z-index: 300; display: grid; place-items: center; background: #04060d; color: #fff; padding: 20px; text-align: center; }

/* ============================================================
   RESPONSIVE
   ============================================================ */
@media (max-width: 1120px) {
  .duel-rail { display: none; }
  .arena-column { max-width: 1000px; }
  .lobby-grid { grid-template-columns: minmax(360px, 0.95fr) minmax(440px, 1.05fr); }
}
@media (max-width: 900px) {
  body { overflow: auto; }
  .lobby-screen { padding: 12px 12px 10px; gap: 12px; }
  .lobby-grid { grid-template-columns: 1fr; }
  .brand-copy h1 { font-size: 34px; }
  .brand-mark { width: 38px; height: 44px; }
  .server-pill { display: none; }
  .room-list { max-height: 340px; }
  .rules-strip { gap: 12px; }
  .build-tag { display: none; }
  .duel-screen { padding: 0 6px 6px; }
  .duel-layout { gap: 0; }
  .hud { gap: 7px; padding: 6px 8px; }
  .hud-id { min-width: 0; max-width: 88px; }
  .hud-id strong { font-size: 11px; }
  .hud-counters { display: none; }
  .lp-block { min-width: 100px; }
  .lp-num { min-width: 48px; }
  .lp-num span { font-size: 14px; }
  .energy-block { min-width: 92px; padding: 3px 6px; gap: 5px; }
  .energy-pips i { width: 5px; height: 10px; }
  .end-turn-btn { padding: 0 9px; font-size: 8px; }
  .end-turn-btn small { display: none; }
  .arena { padding: 17px 6px 15px; }
  .zone-grid { gap: 3px; }
  .hand-card { width: 82px; }
  .hand { justify-content: flex-start; min-height: 112px; }
  .hand-tip { display: none; }
  .hand-wrap { gap: 3px; }
  .turn-chip { padding: 0 10px; }
  .turn-chip small { display: none; }
  .mini-stat { display: none; }
}
@media (max-width: 620px) {
  .topbar { gap: 10px; }
  .brand { gap: 9px; }
  .brand-copy h1 { font-size: 29px; }
  .brand-copy p { font-size: 7px; letter-spacing: 0.28em; }
  .online-pill { height: 30px; padding: 0 9px; font-size: 8px; }
  .online-pill b { font-size: 8px; }
  .panel-head { padding: 14px 14px 0; }
  .panel-head h2 { font-size: 18px; }
  .code-row { margin: 11px 14px 0; }
  .code-note { display: none; }
  .vs-slots { margin: 11px 14px 0; grid-template-columns: 1fr; gap: 7px; }
  .vs-mark { height: 16px; }
  .vs-mark span { font-size: 10px; }
  .slot { min-height: 82px; padding: 10px 11px; }
  .avatar { width: 38px; height: 38px; font-size: 12px; }
  .radar { width: 38px; height: 38px; }
  .room-meta { margin: 11px 14px 0; }
  .room-meta div { padding: 7px 8px; }
  .room-meta strong { font-size: 12px; }
  .primary-btn { margin: 12px 14px 0; min-height: 48px; }
  .hint { margin: 8px 14px 0; }
  .list-head { margin: 11px 14px 0; grid-template-columns: 1.6fr 0.8fr 0.8fr 64px; }
  .list-head span:nth-child(3), .room-row .row-ping { display: none; }
  .room-row { grid-template-columns: 1.6fr 0.8fr 0.8fr 64px; padding: 8px 6px; }
  .room-list { padding: 3px 8px; max-height: 280px; }
  .list-foot { margin: 7px 14px 12px; font-size: 8.5px; }
  .rules-strip span { font-size: 7px; gap: 4px; }
  .rules-strip { gap: 9px; }
  .lobby-screen { padding-bottom: 8px; }

  .duel-topbar { height: 42px; }
  .back-btn { height: 28px; padding: 0 9px; font-size: 8px; }
  .turn-chip { height: 28px; padding: 0 9px; }
  .turn-chip b { font-size: 8.5px; letter-spacing: 0.1em; }
