.hint { margin: 10px 20px 0; font-size: 10px; line-height: 1.6; color: var(--dim); letter-spacing: 0.03em; }

/* deck preview fills the command panel */
.room-extra {
  margin: 14px 20px 0;
  padding-top: 12px;
  border-top: 1px solid var(--line);
  margin-top: auto;
}
.extra-head { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
.extra-side { font-family: var(--mono); font-size: 7px; letter-spacing: 0.14em; color: var(--dim); }
.deck-strip { display: flex; gap: 7px; margin-top: 9px; }
.mini-card {
  position: relative;
  flex: 1;
  min-width: 0;
  height: 82px;
  border: 1px solid color-mix(in srgb, var(--c) 42%, transparent);
  border-radius: 7px;
  background:
    radial-gradient(circle at 50% 30%, color-mix(in srgb, var(--c) 25%, transparent), transparent 62%),
    linear-gradient(160deg, color-mix(in srgb, var(--c) 14%, #0a1224), #050812 76%);
  box-shadow: inset 0 0 14px color-mix(in srgb, var(--c) 7%, transparent);
  overflow: hidden;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.mini-card:hover { transform: translateY(-4px); box-shadow: 0 10px 22px rgba(0, 0, 0, 0.45), 0 0 18px color-mix(in srgb, var(--c) 24%, transparent); }
.mini-card::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(115deg, transparent 25%, rgba(255, 255, 255, 0.12) 48%, transparent 65%);
  transform: translateX(-130%);
  animation: holo-sweep 5.4s ease-in-out infinite;
  animation-delay: calc(var(--i, 0) * -0.55s);
}
.mini-card .mc-cost {
  position: absolute;
  top: 4px;
  left: 4px;
  width: 14px;
  height: 14px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  border: 1px solid color-mix(in srgb, var(--c) 70%, transparent);
  background: rgba(3, 7, 16, 0.9);
  color: var(--c);
  font-family: var(--mono);
  font-size: 7px;
  z-index: 2;
}
.mini-card .mc-glyph {
  position: absolute;
  inset: 16px 0 20px;
  display: grid;
  place-items: center;
  color: var(--c);
  font-size: 23px;
  text-shadow: 0 0 14px var(--c);
  animation: glyph-breathe 4.2s ease-in-out infinite;
}
.mini-card .mc-name {
  position: absolute;
  left: 3px;
  right: 3px;
  bottom: 4px;
  font-family: var(--mono);
  font-size: 6px;
  letter-spacing: 0.02em;
  text-align: center;
  color: #c9ddf7;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  z-index: 2;
}
.flow-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1px;
  margin-top: 10px;
  border: 1px solid var(--line);
  border-radius: 8px;
  overflow: hidden;
  background: var(--line);
}
.flow-row div {
  display: grid;
  grid-template-columns: auto 1fr;
  grid-template-rows: auto auto;
  column-gap: 7px;
  row-gap: 1px;
  padding: 7px 9px;
  background: rgba(5, 9, 21, 0.9);
}
.flow-row i { grid-row: 1 / 3; align-self: center; font-family: var(--mono); font-style: normal; font-size: 9px; color: var(--cyan); opacity: 0.7; }
.flow-row b { font-family: var(--mono); font-size: 7px; letter-spacing: 0.1em; color: var(--ink); }
.flow-row span { font-size: 7.5px; color: var(--dim); line-height: 1.4; }

