import { Duel } from './assets/duel.js';
const g = new Duel();
g.setup(); let guard=0;
function playerTurn(){ g.startTurn('player'); let plays=0; while(plays++<4){ const opts=g.hand.player.map((c,i)=>({c,i})).filter(o=>o.c.cost<=g.energy.player); if(!opts.length)break; opts.sort((a,b)=>b.c.atk-a.c.atk); const z=g.emptyZones('player')[0]; if(!z)break; g.playCard('player',opts[0].i,z.id);} let n=0; while(n++<12 && !g.over){ const u=g.units('player').filter(u=>g.canAttack(u)).sort((a,b)=>g.effectiveAtk(b)-g.effectiveAtk(a))[0]; if(!u)break; const prev=g.previewAttack('player',u.zoneId,null); if(!prev)break; if(prev.badTrade && !prev.lethal){u.hasAttacked=true;continue;} g.attack('player',u.zoneId,prev.targetZoneId);} g.endTurn(); }
function aiTurn(){ g.startTurn('ai'); for(let i=0;i<4;i++){ if(g.over)break; const p=g.aiPlanCard(); if(!p)break; g.playCard('ai',p.handIndex,p.zoneId);} let n=0; while(n++<12 && !g.over){ const p=g.aiBestAttack(); if(!p)break; g.attack('ai',p.fromZoneId,p.targetZoneId);} g.endTurn(); }
while(!g.over && guard++<50){ playerTurn(); if(g.over)break; aiTurn(); }
console.log('over',g.over,'winner',g.winner,'lp',g.lp,'turns',g.globalTurn,'stats',g.stats);
"

