import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const browser = await chromium.launch({ ...config.browser.launchOptions })
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
page.setDefaultTimeout(30000)
page.on('pageerror', e => console.log('PAGEERROR:', e.message))
page.on('console', m => { if (m.type() === 'error') console.log('CONSOLE ERROR:', m.text()) })

const state = () => page.evaluate(() => window.__duel24.state())
const detail = () => page.evaluate(() => {
  const d = window.__duel24.duel
  return {
    active: d.active, over: d.over,
    lp: { ...d.lp },
    turns: { ...d.turns },
    hand: d.hand.player.map(c => ({ name: c.name, cost: c.cost, atk: c.atk })),
    energy: d.energy.player,
    units: d.units('player').map(u => ({ zone: u.zoneId, col: d.zoneById(u.zoneId).col, atk: d.effectiveAtk(u), can: d.canAttack(u), defender: !!d.findDefender('player', d.zoneById(u.zoneId).col) })),
  }
})
const waitPlayer = () => page.waitForFunction(() => {
  const s = window.__duel24.state()
  return s.active === 'player' && !s.busy && !s.over
}, null, { timeout: 45000 })

await page.goto('http://localhost:3000', { waitUntil: 'load' })
await page.waitForTimeout(1500)
await page.click('#startBtn')
await page.waitForTimeout(3500)

// Summon up to two cards in different columns.
const picks = await page.evaluate(() => {
  const d = window.__duel24.duel
  const out = []
  const cols = [0, 5, 2, 4, 1, 3]
  for (let i = 0; i < d.hand.player.length && out.length < 2; i++) {
    const card = d.hand.player[i]
    if (card.cost <= d.energy.player - out.reduce((n, p) => n + p.cost, 0)) {
      out.push({ index: i, cost: card.cost, name: card.name })
    }
  }
  return out.map((p, n) => ({ ...p, col: cols[n] }))
})
console.log('picks', picks)

let energyLeft = (await detail()).energy
for (const pick of picks) {
  if (pick.cost > energyLeft) continue
  const handIndex = await page.evaluate(name => window.__duel24.duel.hand.player.findIndex(c => c.name === name), pick.name)
  await page.locator('.hand-card').nth(handIndex).click()
  await page.waitForTimeout(150)
  const targetZone = 18 + pick.col // player front row
  const isFree = await page.evaluate(z => !window.__duel24.duel.zoneById(z).unit, targetZone)
  const zoneId = isFree ? targetZone : await page.evaluate(() => window.__duel24.duel.emptyZones('player')[0].id)
  await page.locator(`.zone[data-zone="${zoneId}"]`).click()
  await page.waitForTimeout(700)
  energyLeft -= pick.cost
}
console.log('after summon', await detail())

// Fresh summon should inspect as STANDBY.
const unitSel = await page.evaluate(() => {
  const d = window.__duel24.duel
  const u = d.units('player')[0]
  return u ? `.zone[data-zone="${u.zoneId}"] .unit` : null
})
if (unitSel) {
  await page.locator(unitSel).hover()
  await page.waitForTimeout(200)
  console.log('inspector status:', await page.locator('.inspect-meta span').last().textContent())
}

// Find a direct lane after the AI's turn, looping turns if needed.
let open = null
for (let attempt = 0; attempt < 5 && !open; attempt++) {
  await page.click('#endTurnBtn')
  await waitPlayer()
  open = await page.evaluate(() => {
    const d = window.__duel24.duel
    const u = d.units('player').find(u => d.canAttack(u) && !d.findDefender('player', d.zoneById(u.zoneId).col))
    return u ? { zone: u.zoneId, col: d.zoneById(u.zoneId).col, atk: d.effectiveAtk(u) } : null
  })
  console.log('search turn', attempt, await detail(), 'open', open)
  if (!open) {
    // Summon something cheap before ending the next turn.
    if ((await detail()).energy > 0) {
      const idx = await page.evaluate(() => {
        const d = window.__duel24.duel
        return d.hand.player.findIndex(c => c.cost <= d.energy.player)
      })
      if (idx >= 0) {
        await page.locator('.hand-card').nth(idx).click()
        await page.waitForTimeout(120)
        const z = await page.evaluate(() => window.__duel24.duel.emptyZones('player')[0]?.id)
        if (z !== undefined) await page.locator(`.zone[data-zone="${z}"]`).click()
        await page.waitForTimeout(500)
      }
    }
  }
}
if (!open) { console.log('NO DIRECT LANE FOUND'); await browser.close(); process.exit(1) }

// Damage one direct hit and verify LP actually drops.
await page.evaluate(() => { window.__duel24.duel.lp.ai = 1400; window.__duel24.game.renderHud() })
await page.locator(`.zone[data-zone="${open.zone}"] .unit`).click()
await page.waitForTimeout(250)
const tags = await page.locator('.target-tag').allTextContents()
console.log('target tags:', tags)
const target = 6 + open.col
await page.locator(`.zone[data-zone="${target}"]`).click()
await page.waitForTimeout(1400)
const afterHit = await detail()
console.log('after direct hit', { lp: afterHit.lp, expected: 1400 - open.atk })
if (afterHit.lp.ai !== Math.max(0, 1400 - open.atk)) console.log('DIRECT DAMAGE MISMATCH')

// Finish the duel with a lethal direct hit.
const finish = await page.evaluate(() => {
  const d = window.__duel24.duel
  const u = d.units('player').find(u => d.canAttack(u))
  return u ? { zone: u.zoneId, col: d.zoneById(u.zoneId).col } : null
})
console.log('finish unit', finish)
if (finish) {
  await page.evaluate(() => { window.__duel24.duel.lp.ai = 1; window.__duel24.game.renderHud() })
  await page.locator(`.zone[data-zone="${finish.zone}"] .unit`).click()
  await page.waitForTimeout(200)
  await page.locator(`.zone[data-zone="${6 + finish.col}"]`).click()
  await page.waitForTimeout(1800)
  console.log('over?', (await detail()).over, 'result visible', await page.locator('#result').isVisible())
  console.log('result title', await page.locator('#resultTitle').textContent())
  await page.screenshot({ path: 'screenshots/result-desktop.png', timeout: 60000 })
}
console.log('final', await detail())
await browser.close(); process.exit(0)

