import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const browser = await chromium.launch({ ...config.browser.launchOptions })
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
page.setDefaultTimeout(30000)
const errors = []
const bad = []
page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message))
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()) })
page.on('response', r => { if (r.status() >= 400) bad.push(r.status() + ' ' + r.url()) })

const state = () => page.evaluate(() => window.__duel24.state())
const waitPlayer = () => page.waitForFunction(() => {
  const s = window.__duel24.state()
  return s.over || (s.active === 'player' && !s.busy)
}, null, { timeout: 60000 })

await page.goto('http://localhost:3000', { waitUntil: 'load' })
await page.waitForTimeout(1600)
await page.click('#startBtn')
await page.waitForTimeout(3400)

for (let round = 0; round < 20; round++) {
  let s = await state()
  if (s.over) break
  console.log('round', round, s)

  // Summon everything affordable.
  for (let n = 0; n < 8; n++) {
    const pick = await page.evaluate(() => {
      const d = window.__duel24.duel
      if (d.over || d.active !== 'player') return null
      const i = d.hand.player.findIndex(c => c.cost <= d.energy.player)
      return i >= 0 ? i : null
    })
    if (pick === null) break
    await page.locator('.hand-card').nth(pick).click({ force: true })
    await page.waitForTimeout(120)
    const zone = await page.evaluate(() => {
      const d = window.__duel24.duel
      return d.emptyZones('player').sort((a, b) => a.row - b.row)[0]?.id ?? null
    })
    if (zone === null) break
    await page.locator(`.zone[data-zone="${zone}"]`).click({ force: true })
    await page.waitForTimeout(500)
    if ((await state()).over) break
  }

  // Attack with every ready unit, preferring lethal/direct lanes.
  for (let n = 0; n < 8; n++) {
    const unit = await page.evaluate(() => {
      const d = window.__duel24.duel
      if (d.over || d.active !== 'player') return null
      const u = d.units('player').find(u => d.canAttack(u))
      return u ? { zone: u.zoneId, col: d.zoneById(u.zoneId).col } : null
    })
    if (!unit) break
    await page.locator(`.zone[data-zone="${unit.zone}"] .unit`).click({ force: true })
    await page.waitForTimeout(160)
    const target = await page.evaluate(() => {
      const tags = [...document.querySelectorAll('.zone.targetable')]
      const lethal = tags.find(z => z.querySelector('.target-tag')?.textContent === 'LETHAL')
      const direct = tags.find(z => z.querySelector('.target-tag')?.textContent === 'DIRECT')
      const pickEl = lethal || direct || tags[0]
      return pickEl ? Number(pickEl.dataset.zone) : null
    })
    if (target === null) break
    await page.locator(`.zone[data-zone="${target}"]`).click({ force: true })
    await page.waitForTimeout(1100)
    const after = await state()
    if (after.over) break
  }

  s = await state()
  if (s.over) break
  await page.locator('#endTurnBtn').click({ force: true })
  await waitPlayer()
  if ((await state()).over) break
}

await page.waitForTimeout(1200)
const final = await state()
console.log('FINAL', final)
if (final.over) {
  console.log('result visible', await page.locator('#result').isVisible())
  console.log('title', await page.locator('#resultTitle').textContent(), '|', await page.locator('#resultSub').textContent())
  console.log('stats', await page.locator('.result-stats').innerText())
  await page.screenshot({ path: 'screenshots/result-natural.png', timeout: 60000 })
}
console.log('errors', errors)
console.log('bad', bad)
await browser.close(); process.exit(0)

