import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const browser = await chromium.launch({ ...config.browser.launchOptions })

const sizes = [
  { w: 360, h: 640, name: 'small-phone' },
  { w: 320, h: 568, name: 'tiny-phone' },
  { w: 768, h: 1024, name: 'tablet' },
  { w: 844, h: 390, name: 'landscape' },
]
for (const size of sizes) {
  const page = await browser.newPage({ viewport: { width: size.w, height: size.h }, isMobile: true, hasTouch: true })
  page.setDefaultTimeout(30000)
  const errors = []
  page.on('pageerror', e => errors.push(e.message))
  await page.goto('http://localhost:3000', { waitUntil: 'load' })
  await page.waitForTimeout(1400)
  const lobby = await page.evaluate(() => ({
    scrollW: document.documentElement.scrollWidth,
    bodyH: document.body.scrollHeight,
    innerW: innerWidth, innerH: innerHeight,
    start: (() => { const r = document.querySelector('#startBtn').getBoundingClientRect(); return { y: r.y, h: r.height, bottom: r.bottom } })(),
    list: (() => { const r = document.querySelector('.room-list').getBoundingClientRect(); return { y: r.y, h: r.height, bottom: r.bottom } })(),
  }))
  await page.click('#startBtn')
  await page.waitForTimeout(3400)
  const duel = await page.evaluate(() => {
    const rect = s => { const r = document.querySelector(s)?.getBoundingClientRect(); return r ? { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height), bottom: Math.round(r.bottom) } : null }
    const zone = rect('.zone')
    return {
      scrollW: document.documentElement.scrollWidth,
      bodyH: document.body.scrollHeight,
      innerW: innerWidth, innerH: innerHeight,
      arena: rect('#arena'), board: rect('#board'), zone,
      hand: rect('#hand'), endTurn: rect('#endTurnBtn'),
      playerHud: rect('#playerHud'),
    }
  })
  console.log(size.name, { lobby, duel, errors })
  await page.screenshot({ path: `screenshots/responsive-${size.name}.png`, timeout: 20000, animations: 'disabled' }).catch(e => console.log('shot fail', size.name, e.message.split('\n')[0]))
  await page.close()
}
await browser.close(); process.exit(0)

