import { createRequire } from 'node:module'
import { readFileSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const browser = await chromium.launch({ ...config.browser.launchOptions })
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
page.setDefaultTimeout(30000)
const errors = []
page.on('pageerror', e => { errors.push(e.message); console.log('PAGEERROR', e.message) })
await page.goto('http://localhost:3000', { waitUntil: 'load' })
await page.waitForTimeout(1500)
await page.click('#startBtn')
await page.waitForTimeout(3400)

await page.evaluate(() => {
  const d = window.__duel24.duel
  d.lp.player = 0
  d.checkOver()
  window.__duel24.game.checkOver()
})
await page.waitForTimeout(1400)
console.log('defeat title', await page.locator('#resultTitle').textContent(), '| visible', await page.locator('#result').isVisible())
try {
  await page.screenshot({ path: 'screenshots/result-defeat.png', timeout: 12000, animations: 'disabled' })
} catch {
  const cdp = await page.context().newCDPSession(page)
  const shot = await cdp.send('Page.captureScreenshot', { format: 'png', fromSurface: true })
  writeFileSync('screenshots/result-defeat.png', Buffer.from(shot.data, 'base64'))
}

await page.locator('#rematchBtn').click({ force: true })
await page.waitForTimeout(2200)
console.log('rematch', await page.evaluate(() => ({
  ...window.__duel24.state(),
  resultHidden: document.querySelector('#result').classList.contains('hidden'),
})))

// Trigger defeat again, then return to the lobby from the result card.
await page.evaluate(() => {
  const d = window.__duel24.duel
  d.lp.player = 0
  d.checkOver()
  window.__duel24.game.checkOver()
})
await page.waitForTimeout(1300)
await page.locator('#toLobbyBtn').click({ force: true })
await page.waitForTimeout(600)
