import { createRequire } from 'node:module'
import { readFileSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const browser = await chromium.launch({ ...config.browser.launchOptions })
const page = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true })
page.setDefaultTimeout(30000)
const errors = []
const bad = []
page.on('pageerror', e => errors.push(e.message))
page.on('response', r => { if (r.status() >= 400) bad.push(r.status() + ' ' + r.url()) })
await page.goto('http://localhost:3000', { waitUntil: 'load' })
await page.waitForTimeout(11000)
console.log(await page.evaluate(() => ({
  room: document.querySelector('#roomCode').textContent,
  opponent: document.querySelector('#opponentSlot').innerText.replace(/\n/g, ' | '),
  startSub: document.querySelector('#startBtn .btn-sub').textContent,
  auto: document.querySelector('#autoTimer').textContent,
  scrollW: document.documentElement.scrollWidth,
  innerW: innerWidth,
})))
try {
  await page.screenshot({ path: 'screenshots/lobby-mobile.png', timeout: 20000, animations: 'disabled' })
} catch {
  const cdp = await page.context().newCDPSession(page)
  const shot = await cdp.send('Page.captureScreenshot', { format: 'png', fromSurface: true })
  writeFileSync('screenshots/lobby-mobile.png', Buffer.from(shot.data, 'base64'))
}
console.log('errors', errors, 'bad', bad)
await browser.close(); process.exit(0)

